targets.expr:
sum by (method, endpoint_normalized, status) (
  label_replace(
    label_replace(
      label_replace(
        label_replace(
          rate(http_requests_total{endpoint=~"/api/.*"}[5m]),
          "endpoint_normalized", "$1", "endpoint", "^(.*)$"
        ),
        "endpoint_normalized", "/api/v1/matches/*", "endpoint", "/api/v1/matches/.*"
      ),
      "endpoint_normalized", "/api/v1/scorecard/*", "endpoint", "/api/v1/scorecard/.*"
    ),
    "endpoint_normalized", "/api/v1/series/*", "endpoint", "/api/v1/series/.+"
  )
)

